// Noto Sans (OFL), subset to Basic Latin + Latin-1 Supplement + Latin Extended-A
// plus common punctuation/currency (em dash, curly quotes, euro sign) — covers
// French/German/Spanish/Nordic/Czech/Polish/Slovak diacritics for invoice PDFs.
// jsPDF's built-in fonts (Helvetica/Times/Courier) only support WinAnsi, which
// drops Central/Eastern European characters like č, ř, ě, ů — this fixes that.
// Kept as a format-2.0 post table (--glyph-names) — jsPDF's TTF parser cannot
// read the format-3.0 post table fontTools produces by default.
export const NOTO_SANS_REGULAR_BASE64 = "";

export const NOTO_SANS_BOLD_BASE64 = "";
